powerpagecomponent.content:
{
  "source": "<!doctype html><html><head><title>Enhanced fixture</title></head><body>
<h1 id="who">{{ user.fullname | default: "Anonymous" }}</h1>
{% include 'Partial' %}
<p id="greeting">{{ snippets["Greeting"] }}</p>
<p id="banner">{{ settings["Feature/Banner"] }}</p>
{% fetchxml contacts %}<fetch><entity name="contact"><attribute name="fullname"/></entity></fetch>{% endfetchxml %}
<p id="count">{{ contacts.results.entities.size }}</p>
</body></html>"
}
